PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS organization_members (organization_id TEXT NOT NULL, user_id TEXT NOT NULL, role TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (organization_id, user_id));
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, name TEXT NOT NULL, slug TEXT NOT NULL, public_key TEXT NOT NULL UNIQUE, server_key_hash TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, UNIQUE (organization_id, slug));
CREATE TABLE IF NOT EXISTS project_settings (project_id TEXT PRIMARY KEY, theme_json TEXT NOT NULL DEFAULT '{}', allowed_metadata_json TEXT NOT NULL DEFAULT '[]', retention_days INTEGER NOT NULL DEFAULT 365, origins_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS feedback_items (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, project_id TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('complaint','bug','suggestion','feature_request')), status TEXT NOT NULL CHECK(status IN ('new','triaged','planned','in_progress','resolved','closed','spam')), priority TEXT NOT NULL DEFAULT 'normal', title TEXT NOT NULL, body TEXT NOT NULL, email TEXT, platform TEXT, app_version TEXT, os_version TEXT, locale TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE INDEX IF NOT EXISTS idx_feedback_project_created ON feedback_items(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_feedback_tenant_status ON feedback_items(organization_id, project_id, status, created_at DESC);
CREATE TABLE IF NOT EXISTS feedback_comments (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, project_id TEXT NOT NULL, feedback_id TEXT NOT NULL, author_user_id TEXT, body TEXT NOT NULL, is_internal INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS feedback_votes (feedback_id TEXT NOT NULL, voter_fingerprint TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (feedback_id, voter_fingerprint));
CREATE TABLE IF NOT EXISTS feedback_status_history (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, project_id TEXT NOT NULL, feedback_id TEXT NOT NULL, from_status TEXT, to_status TEXT NOT NULL, actor_user_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, project_id TEXT NOT NULL, feedback_id TEXT NOT NULL, object_key TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, created_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, project_id TEXT NOT NULL, name TEXT NOT NULL, slug TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roadmap_items (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, project_id TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS changelog_items (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, project_id TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, published_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS webhooks (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, project_id TEXT NOT NULL, url TEXT NOT NULL, secret_hash TEXT NOT NULL, events_json TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_deliveries (id TEXT PRIMARY KEY, webhook_id TEXT NOT NULL, event_id TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT, created_at TEXT NOT NULL, UNIQUE(webhook_id, event_id));
CREATE TABLE IF NOT EXISTS magic_link_tokens (id TEXT PRIMARY KEY, feedback_id TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subscriptions (organization_id TEXT PRIMARY KEY, plan TEXT NOT NULL DEFAULT 'free', status TEXT NOT NULL DEFAULT 'active', provider_customer_id TEXT, provider_subscription_id TEXT, current_period_end TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage_counters (organization_id TEXT NOT NULL, period TEXT NOT NULL, feedback_count INTEGER NOT NULL DEFAULT 0, attachment_bytes INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (organization_id, period));
CREATE TABLE IF NOT EXISTS moderation_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, project_id TEXT NOT NULL, feedback_id TEXT NOT NULL, kind TEXT NOT NULL, outcome TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, project_id TEXT, actor_user_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
